contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public payable {
        uint before;
        uint observed;
        bool reverted;

        before = c.MinSum(); if (__ESBMC_reverted()) return;

        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        observed = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(reverted ? (observed == before) : (observed == _val));
    }

    receive() external payable {}
}

