pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 _val) internal {
        uint before;
        uint observed;
        bool reverted;
        try c.MinSum() returns (uint256 __r) { before = __r; } catch { return; }
        try c.SetMinSum(_val) { reverted = false; } catch { reverted = true; }
        try c.MinSum() returns (uint256 __r) { observed = __r; } catch { return; }
        assertTrue(reverted ? (observed == before) : (observed == _val));
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
